args.sparql:
SELECT DISTINCT ?director ?directorLabel WHERE {
  { dbr:The_Strange_Case_of_Mary_Page dbo:director ?director } UNION { dbr:The_Strange_Case_of_Mary_Page dbp:director ?director }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
}

SELECT DISTINCT ?birthPlace ?birthPlaceLabel WHERE {
  { dbr:J._Charles_Haydon dbo:birthPlace ?birthPlace } UNION { dbr:J._Charles_Haydon dbp:birthPlace ?birthPlace }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel) = "en") }
}

SELECT DISTINCT ?birthPlace ?birthPlaceLabel WHERE {
  { dbr:The_Strange_Case_of_Mary_Page dbo:director ?director } UNION { dbr:The_Strange_Case_of_Mary_Page dbp:director ?director } .
  { ?director dbo:birthPlace ?birthPlace } UNION { ?director dbp:birthPlace ?birthPlace } .
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER(lang(?birthPlaceLabel) = "en") }
}

